/*
 * Internal state for the PRNG, should be initialized via mp_rand_seed().
 * A state is not thread-safe: it must not be shared between threads without
 * external synchronization.
 */
struct mp_rand_state {
    uint64_t v[4];
};

/*
 * Return a PRNG state initialized from the given 64-bit seed. If the seed is
 * 0, the state is randomized. The returned state must be stored by the caller
 * and passed to mp_rand_next*(); the return value must not be ignored.
 */
struct mp_rand_state mp_rand_seed(uint64_t seed);

